const ALL=[...SUBSCRIPTIONS,...ONEOFF];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const eur=n=>n==null?'Индивидуална цена':new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(n)||0);
const qty=(v,min=0)=>Math.max(min,Number(v)||0);
const day=()=>new Date().toISOString().slice(0,10);
const orderKey='blis-commerce-orders-v2';
const state={tab:'catalog',catalogType:'subscriptions',selected:'analysis',detail:null,orders:load(),active:null,billing:'monthly',addons:new Set()};
function load(){try{return JSON.parse(localStorage.getItem(orderKey)||'[]')}catch(_){return[]}}
function save(){try{localStorage.setItem(orderKey,JSON.stringify(state.orders))}catch(_){}}
function service(id){return ALL.find(x=>x.id===id)||SUBSCRIPTIONS[1]}
function clientSlug(){return document.body?.dataset?.client||window.BLIS_INITIAL_CLIENT||'client'}
function currentClient(){return document.querySelector('.client-brand-name')?.textContent?.trim()||'Клиентски профил'}
function orderId(){return `BLIS-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${Math.random().toString(36).slice(2,7).toUpperCase()}`}
function setupLabel(s){if(!s.setupMin)return 'Без първоначална такса';if(s.setupMax==null||s.setupMax!==s.setupMin)return `от ${eur(s.setupMin)}`;return eur(s.setupMin)}
function priceLabel(s){return `${s.from?'от ':''}${eur(s.price)}`}
function timingLabel(s){return s.duration||'Срокът се потвърждава при заявка'}
function relevantOrders(){return state.orders.filter(o=>o.clientSlug===clientSlug())}
function activeOrder(){return state.orders.find(o=>o.id===state.active)||relevantOrders()[0]||null}

